-- Egna teman: colour themes an administrator installs under System → Teman
-- (theme file or editor). Token values only — the server validates them
-- against the catalogue and builds the CSS itself. key is generated by the
-- server ("egen-" + 8 hex); name is unique regardless of case (themes_name_unique
-- on lower(name)). No backfill: the built-in themes stay in tokens.css.
CREATE TYPE "public"."theme_scheme" AS ENUM('light', 'dark');--> statement-breakpoint
CREATE TABLE "themes" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"key" varchar(40) NOT NULL,
	"name" varchar(60) NOT NULL,
	"scheme" "theme_scheme" NOT NULL,
	"tokens" jsonb NOT NULL,
	"source" jsonb,
	"created_by" uuid,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_by" uuid,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "themes_key_unique" UNIQUE("key")
);
--> statement-breakpoint
ALTER TABLE "themes" ADD CONSTRAINT "themes_created_by_users_id_fk" FOREIGN KEY ("created_by") REFERENCES "public"."users"("id") ON DELETE set null ON UPDATE no action;--> statement-breakpoint
ALTER TABLE "themes" ADD CONSTRAINT "themes_updated_by_users_id_fk" FOREIGN KEY ("updated_by") REFERENCES "public"."users"("id") ON DELETE set null ON UPDATE no action;--> statement-breakpoint
CREATE UNIQUE INDEX "themes_name_unique" ON "themes" USING btree (lower("name"));